$main: nova-table;

.#{$main} {
  --el-table-header-bg: #f0f4fa;
  box-sizing: border-box;

  &__filter {
    margin-bottom: 8px;
  }

  &__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-bottom: 16px;
    &-right {
      display: flex;
      align-items: center;
      justify-content: flex-end;
      .el-button.is-circle {
        border-radius: var(--el-border-radius-base);
      }
      .el-icon {
        font-size: 16px;
      }
    }
  }

  :deep(.el-table__header-wrapper th) {
    background-color: var(--el-table-header-bg);
  }

  &__footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-top: 16px;
    &--selections {
      display: inline-flex;
      align-items: center;
      font-size: var(--el-font-size-base);

      .selections-warning {
        margin-right: 4px;
        color: var(--el-color-primary);
      }

      .selections-count {
        margin: 0 4px;
        color: var(--el-color-primary);
      }
    }
  }

  .cursor-move {
    cursor: move;
  }

  .table-empty {
    line-height: 22px;
    .el-empty__description {
      margin-top: 0;
    }
  }

  &-card {
    .#{$main}__filter {
      padding: 16px 24px;
      border-radius: 4px;
      background: #fff;
    }

    .#{$main}__main {
      padding: 16px 24px;
      border-radius: 4px;
      background: #fff;
    }
  }

  &-full-height {
    display: flex;
    flex-direction: column;
    height: 100%;
    .#{$main}__main {
      flex: 1;
      display: flex;
      flex-direction: column;
      min-height: 0;
      .el-table {
        flex: 1;
      }
    }
  }
}

.#{$main}-draggable {
  &-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 8px;
    border-radius: 4px;
    cursor: move;
    &:hover {
      background: #f2f2f2;
    }
    &.draging {
      background: transparent;
    }

    &.unmover {
      cursor: default;
      &:hover {
        background: transparent;
      }
    }
  }
  &-fixed {
    width: 16px;
    height: 16px;
    margin-left: auto;
    margin-right: 8px;
  }
}

.nova-table-setting-popover {
  &.el-popover.el-popper {
    padding: 8px;
  }
  &__filter {
    margin: 0 8px;
  }
  &__title {
    position: sticky;
    top: 0;
    margin-bottom: 4px;
    padding: 8px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-size: var(--el-font-size-base);
    color: var(--el-text-color-primary);
    line-height: 20px;
    font-weight: 600;
    // border-bottom: 1px solid #e6e6e6;
    background-color: #fff;
    z-index: 1;
    &::before {
      position: absolute;
      bottom: 0;
      left: 8px;
      content: '';
      height: 1px;
      width: calc(100% - 16px);
      background: #e6e6e6;
    }
    span {
      color: var(--el-text-color-secondary);
      font-weight: 400;
    }
    &.unchoose-title {
      top: 36px;
      bottom: 0;
    }
  }

  &__footer {
    margin-top: 8px;
    padding: 0 8px;
    display: flex;
    justify-content: space-between;
  }

  .nova-table-draggable-wraper {
    &--disabled {
      .nova-table-draggable-item {
        cursor: default;
      }
    }
  }

  .nova-table-draggable-wraper,
  .nova-table-draggable-item {
    position: relative;
    z-index: 0;
  }
}

.nova-draggable-tips {
  width: 10px;
  .nova-draggable-row {
    display: flex;
    align-items: center;
    justify-content: space-around;
    margin-bottom: 2px;
    &:last-child {
      margin-bottom: 0;
    }
    .nova-draggable-col {
      display: inline-block;
      width: 2px;
      height: 2px;
      border-radius: 50%;
      background: #959595;
    }
  }
}

